// Verifica que el pedido lo mandó Meta y no cualquiera que descubrió la URL.
// Sin esto, alguien podría inyectarle mensajes falsos al flujo.
const crypto = require('crypto');

const secret = $env.META_APP_SECRET;
if (!secret) {
  throw new Error('Falta la variable de entorno META_APP_SECRET');
}

const item = $input.first();
const firmaRecibida = item.json.headers?.['x-hub-signature-256'];

// Con rawBody activado el cuerpo llega como binario. Hay que firmar esos bytes
// exactos: si re-serializás el JSON, el orden de las claves puede cambiar y la
// firma no coincide nunca.
const crudo = item.binary?.data
  ? Buffer.from(item.binary.data.data, 'base64')
  : Buffer.from(JSON.stringify(item.json.body ?? {}), 'utf8');

const esperada = 'sha256=' + crypto.createHmac('sha256', secret).update(crudo).digest('hex');

// timingSafeEqual en vez de === para no filtrar información por el tiempo que
// tarda la comparación.
let valida = false;
if (typeof firmaRecibida === 'string' && firmaRecibida.length === esperada.length) {
  valida = crypto.timingSafeEqual(Buffer.from(firmaRecibida), Buffer.from(esperada));
}

const cuerpo = item.binary?.data ? JSON.parse(crudo.toString('utf8')) : item.json.body;

return [{ json: { firmaValida: valida, body: cuerpo } }];

// Saca el mensaje del payload y descarta lo que no hay que responder.
const staticData = $getWorkflowStaticData('global');
staticData.procesados = staticData.procesados || [];

const value = $json.body?.entry?.[0]?.changes?.[0]?.value ?? {};

// Los avisos de "entregado" y "leído" llegan al MISMO webhook pero vienen en
// statuses[], no en messages[]. Si no filtrás esto, el bot se contesta solo.
if (!Array.isArray(value.messages) || value.messages.length === 0) {
  return [{ json: { procesar: false, motivo: 'evento de estado, no es un mensaje' } }];
}

const msg = value.messages[0];
const contacto = value.contacts?.[0];

// Meta reintenta hasta 7 días si no recibió un 200, así que el mismo mensaje
// puede llegar varias veces. El wamid es único por mensaje.
if (staticData.procesados.includes(msg.id)) {
  return [{ json: { procesar: false, motivo: 'duplicado: ' + msg.id } }];
}
staticData.procesados.push(msg.id);
if (staticData.procesados.length > 500) {
  staticData.procesados = staticData.procesados.slice(-500);
}

// El texto SOLO existe si type === 'text'. Un audio o una foto no traen
// .text.body y asumir que sí es el error más común al empezar.
return [{
  json: {
    procesar: true,
    wamid: msg.id,
    de: msg.from,
    nombre: contacto?.profile?.name ?? '',
    tipo: msg.type,
    texto: msg.type === 'text' ? (msg.text?.body ?? '') : '',
  },
}];

// Decide qué contestar. Reglas por palabra clave, sin IA: es barato,
// predecible y no inventa precios. La rama de "no sé" deriva a la dueña.
const consulta = $('Extraer mensaje y deduplicar').first().json;

// Si el Sheet falló, esto queda vacío y el flujo deriva a la dueña.
const catalogo = $input.all()
  .map(i => i.json)
  .filter(f => f && (f.Producto || f.producto));

const normalizar = s => String(s ?? '')
  .toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')   // saca acentos
  .replace(/[^a-z0-9\s]/g, ' ')                        // saca signos: "anillado?" no matcheaba
  .replace(/\s+/g, ' ')
  .trim();

const texto = normalizar(consulta.texto);
const saludo = consulta.nombre ? `¡Hola ${consulta.nombre}! ` : '¡Hola! ';

// Un mensaje que no es texto (audio, foto, ubicación) no se puede matchear
// por palabras: va derecho a la dueña.
if (consulta.tipo !== 'text' || !texto) {
  return [{ json: { ...consulta, respondio: false, motivo: `mensaje de tipo ${consulta.tipo}` } }];
}

const tiene = (...palabras) => palabras.some(p => texto.includes(p));

// Busca el producto en el catálogo por coincidencia de palabras.
const buscarEnCatalogo = () => {
  const palabras = texto.split(/\s+/).filter(p => p.length > 3);
  if (!palabras.length) return null;
  return catalogo.find(fila => {
    const nombre = normalizar(fila.Producto ?? fila.producto);
    return palabras.some(p => nombre.includes(p));
  }) ?? null;
};

let respuesta = null;

if (tiene('horario', 'abren', 'abierto', 'cierran', 'atienden')) {
  respuesta = `${saludo}Abrimos de lunes a sábado de 9 a 20:30 hs 🕐`;
}
else if (tiene('donde', 'direccion', 'ubicad', 'llegar', 'quedan')) {
  respuesta = `${saludo}Estamos en Peña 3102, CABA, a metros de Santa Fe 📍`;
}
else {
  const producto = buscarEnCatalogo();
  if (producto) {
    const nombre = producto.Producto ?? producto.producto;
    const precio = producto.Precio ?? producto.precio;
    respuesta = precio
      ? `${saludo}${nombre}: ${precio}. Te lo dejamos listo para retirar 👍`
      : `${saludo}Sí, tenemos ${nombre}. Pasá y lo vemos 👍`;
  }
}

if (!respuesta) {
  return [{ json: { ...consulta, respondio: false, motivo: 'ninguna regla matcheó' } }];
}

return [{ json: { ...consulta, respondio: true, respuesta } }];

